import {prepareArticleModel,readArticleRaw} from '../shared/article-import.js';
await prepareArticleModel('exceptions','thinking-lab:exceptions:v1');
import {capacityPanel,capacitySettings} from './capacity-ui.js?v=0.21.0';
import {configureCapacity,setBudget} from './capacity.js?v=0.21.0';
import {validateBundle,comparePolicy,portable,parse,markdown,editEffort} from './state.js?v=0.21.0';
import {mountShell} from '../shared/shell.js?v=0.22.0';import {escapeHtml as esc,readStore,writeStore,downloadText} from '../shared/utils.js?v=0.24.0';import {attachCardDrag} from '../shared/drag.js?v=0.21.0';import {LANES,create,request,move,preview,advance,runPolicy,configure,active} from './engine.js?v=0.21.0';
mountShell({active:'exceptions'});const KEY='thinking-lab:exceptions:v1',app=document.querySelector('#app');const f=n=>Number(n).toFixed(1),copy=v=>structuredClone(v);let s=create({finite:true}),undo=[],comparisons=[],decision='',message='',dragOff=()=>{},storageOK=true,paused=false,recovery=null;
try{const raw=readArticleRaw(KEY);if(raw){recovery=raw;({s,comparisons,decision}=validateBundle(JSON.parse(raw)));recovery=null;}}catch{paused=true;message='Saved work needs recovery. Saving is paused until you choose to replace it.';}
const say=text=>document.querySelector('#status').textContent=text;function save(){if(paused)return;storageOK=writeStore(KEY,{s,comparisons,decision});}function change(next,text){undo.push(copy({s,comparisons,decision}));undo=undo.slice(-35);s=next;message=text;save();render();say(text);}function attempt(fn){try{fn();}catch(e){message=e.message;render();say(message);}}
function card(e){const r=request(e.id),expired=s.quarter>=r.arrive+r.life;return `<article class="card ${e.plan==='retired'?'retired':''}" data-drag-id="${e.id}"><button class="card-handle" data-drag-handle aria-label="Drag ${esc(r.name)}" ${e.status==='retired'||s.quarter===6?'disabled':''}>${esc(r.name)}</button><p><strong>${expired?'Benefit ended':`+${r.value} value points / quarter`}</strong> <span class="meta">${!expired?`through Q${Math.min(6,r.arrive+r.life)}`:''}</span></p><p class="meta">${r.touches.join(' + ')} · first acceptance +${r.bonus} points</p><p>Value costs: setup ${r.setup} · upkeep ${r.maint} points/q</p><p class="meta">Standardise ${r.standard} · retire ${r.retire} points</p><label class="sr-only" for="move-${e.id}">Move ${esc(r.name)}</label><select id="move-${e.id}" data-move="${e.id}" ${e.status==='retired'||s.quarter===6?'disabled':''}>${Object.entries(LANES).map(([k,v])=>`<option value="${k}" ${e.plan===k?'selected':''} ${k==='pending'&&e.status!=='pending'||k==='tailored'&&e.status==='standard'?'disabled':''}>${v}</option>`).join('')}</select></article>`;}
function render(){const focused=document.activeElement,focusId=focused?.id,focusData=focused?.dataset?JSON.stringify(focused.dataset):null,open=[...app.querySelectorAll('details[open][id]')].map(x=>x.id);dragOff();const done=s.quarter===6,p=done?s.history.at(-1):preview(s);app.innerHTML=`<div class="bar"><div><strong>${done?'Six quarters complete':`Quarter ${s.quarter+1} of 6`}</strong> <span class="meta">Fictional value points · future requests arrive one quarter at a time</span></div><div class="bar-group"><button class="button" id="undo" ${!undo.length?'disabled':''}>Undo</button><button class="button" id="reset">${done?'Replay this sequence':'Reset run'}</button>${!done?`<button class="button primary" id="advance" ${p.capacity&&!p.capacity.feasible?'disabled':''}>Settle quarter & reveal next</button>`:''}</div></div><div class="stats"><div class="stat"><span>${done?'Final accumulated value':'Accumulated value'}</span><strong>${f(s.value)}</strong><small>${s.quarter} quarters settled</small></div><div class="stat"><span>${done?'Last quarter revenue':'This quarter’s revenue'}</span><strong class="good">+${f(p.revenue)}</strong><small>Recurring benefit + first-acceptance benefit</small></div><div class="stat"><span>Change + operating costs (points)</span><strong>${f(p.changeCost+p.maintenance+p.retirement)}</strong><small>${f(p.changeCost)} setup · ${f(p.maintenance)} upkeep · ${f(p.retirement)} exit</small></div><div class="stat"><span>${done?'Last quarter net':'If you settle this plan'}</span><strong class="${p.net>=0?'good':'bad'}">${p.net>=0?'+':''}${f(p.net)}</strong><small>${f(p.reuse)} setup points saved through reuse</small></div></div>${capacityPanel(s,p)}${message?`<p class="notice">${esc(message)}</p>`:''}<div class="board">${Object.entries(LANES).map(([lane,label])=>`<section class="lane" data-drop-id="${lane}"><h2>${label} <span class="meta">${s.entries.filter(e=>e.plan===lane).length}</span></h2><p class="lane-caption">${{pending:'Unchosen requests expire when this quarter settles.',tailored:'Quick setup, recurring upkeep and possible interactions.',standard:'Pay to generalise. Lower upkeep; reusable setup for related work.',retired:'Exit cost for live work; no future benefit or upkeep.'}[lane]}</p><div class="lane-items">${s.entries.filter(e=>e.plan===lane).map(card).join('')||'<p class="empty">Drop a request here, or use its move menu.</p>'}</div></section>`).join('')}</div><div class="two-columns"><section class="panel"><h2>Value costs from shared surfaces</h2>${p.pairs.length?p.pairs.map(pair=>`<div class="list-row"><span>${esc(request(pair.a).name)} × ${esc(request(pair.b).name)}<br><span class="meta">Shared surface: ${pair.overlap.join(', ')}</span></span><strong>${f(pair.cost)} points/q</strong></div>`).join(''):'<p class="hint">No accepted implementations currently share a surface. An isolated exception can remain a good bargain.</p>'}<p class="hint">Standards reduce pair friction to one third and save up to 6 setup points on new related tailored work. Upkeep continues after benefit expires until you retire the work.</p></section><section class="panel"><h2>${done?'Compare rules on this same sequence':'Challenge the cost assumptions'}</h2>${done?`<p class="hint">Both rules see only the requests revealed each quarter and retire work when its benefit ends.</p><div class="bar-group"><button class="button" data-policy="tailor">Keep all requests tailored</button><button class="button" data-policy="reuse">Standardise when ≥3 quarters remain</button></div>${comparisons.length?`<div class="table-wrap"><table><thead><tr><th>Rule</th><th>Value points</th>${s.capacity?'<th>Core days done</th><th>Core days waiting</th>':''}</tr></thead><tbody><tr><td>Your run</td><td>${f(s.value)}</td>${s.capacity?`<td>${f(s.history.reduce((n,h)=>n+h.capacity.coreDone,0))}</td><td>${f(p.capacity.coreRemaining)}</td>`:''}</tr>${comparisons.map(c=>`<tr><td>${esc(c.name)}</td>${c.complete?`<td>${f(c.value)}</td>${s.capacity?`<td>${f(c.coreDone)}</td><td>${f(c.coreRemaining)}</td>`:''}`:`<td colspan="${s.capacity?3:1}">Infeasible in Q${c.quarter+1}: ${f(c.required)} days requested, ${f(c.budget)} available. No completed-run comparison.</td>`}</tr>`).join('')}</tbody></table></div>`:''}}`:`<div class="field"><label for="aging">Extra upkeep per quarter of age <output>${f(s.aging)}</output></label><input id="aging" type="range" min="0" max="3" step="0.1" value="${s.aging}" ${s.quarter?'disabled':''}></div><div class="field"><label for="pairCost">Friction per overlapping pair <output>${f(s.pairCost)}</output></label><input id="pairCost" type="range" min="0" max="6" step="0.5" value="${s.pairCost}" ${s.quarter?'disabled':''}></div><p class="hint">Set these before the first settlement so comparisons keep the same rules. Low interaction costs favour accommodation; high costs can justify generalisation.</p>`}</section></div>${capacitySettings(s)}${s.history.length?`<section class="panel"><h2>The quarters you have settled</h2><div class="table-wrap"><table><thead><tr><th>Quarter</th><th>Revenue</th><th>Setup</th><th>Upkeep + interactions</th><th>Retire</th><th>Net</th>${s.capacity?'<th>Capacity</th><th>Upkeep days</th><th>Core days done</th><th>Core days waiting</th>':''}</tr></thead><tbody>${s.history.map(h=>`<tr><td>Q${h.quarter+1}</td><td>${f(h.revenue)}</td><td>${f(h.changeCost)}</td><td>${f(h.maintenance)}</td><td>${f(h.retirement)}</td><td>${f(h.net)}</td>${h.capacity?`<td>${f(h.capacity.budget)}</td><td>${f(h.capacity.maintenance)}</td><td>${f(h.capacity.coreDone)}</td><td>${f(h.capacity.coreRemaining)}</td>`:''}</tr>`).join('')}</tbody></table></div></section>`:''}<section class="decision"><label for="decision">What would you accept, standardise or retire—and what work would that protect?</label><textarea id="decision" rows="3" maxlength="20000">${esc(decision)}</textarea></section><div class="footer-row"><details><summary>Mechanism and limits</summary><p>Revenue is recurring value while the request is live, plus a first-acceptance bonus. Net value subtracts setup/generalisation, base upkeep, ageing, pair friction and explicit retirement costs. Standard upkeep is 40% of base; standards do not age. A pair is charged once if its surface tags overlap.</p><p>This is a fictional product-maintenance model, not a prediction of customer value. Core work progress is reported separately, not priced into net value. Capacity runs use separate effort estimates and a finite budget. A whole-quarter plan must fit before settlement; remaining days serve named core work in arrival order. There is no partial exception implementation, discounting or hidden probabilistic failure. Retirement is final after settlement; Undo and replay can revisit it. A replay is informed by requests you have already seen.</p></details><div class="bar-group"><button class="button" id="export">Export notes ↓</button><button class="button" id="json">Editable JSON ↓</button><button class="button" id="import">Import ↑</button></div></div>${paused?'<div class="notice"><p>Saving is paused to protect existing work.</p><button class="button" id="recovery">Download recovery copy</button><button class="button" id="resume">Save this run instead</button></div>':''}<p class="save-note">${paused?'Saving paused.':storageOK?'Work stays in this browser. Export a copy to keep it.':'Storage is unavailable; export to keep this run.'}</p>`;bind();dragOff=attachCardDrag({root:app,onDrop:({itemId,dropId})=>attempt(()=>change(move(s,itemId,dropId),'Plan updated; costs settle only when you advance.'))});open.forEach(id=>document.getElementById(id)?.setAttribute('open',''));const focus=focusId?document.getElementById(focusId):focusData&&focusData!=='{}'?[...app.querySelectorAll('input,select,button')].find(x=>JSON.stringify(x.dataset)===focusData):null;focus?.focus({preventScroll:true});}
function bind(){
 app.querySelectorAll('[data-move]').forEach(el=>el.onchange=()=>attempt(()=>change(move(s,el.dataset.move,el.value),'Plan updated.')));
 app.querySelector('#advance')?.addEventListener('click',()=>attempt(()=>change(advance(s),'Quarter settled. New requests, if any, are now visible.')));
 app.querySelector('#undo').onclick=()=>{if(undo.length){({s,comparisons,decision}=undo.pop());message='Last change undone.';save();render();}};
 const reset=()=>{const next={...create({finite:true}),aging:s.aging,pairCost:s.pairCost,...(s.capacity?{capacity:copy(s.capacity)}:{})};change(next,'Same sequence restarted with capacity. Undo restores the previous run.');comparisons=[];save();render();};app.querySelector('#reset').onclick=reset;app.querySelector('#finite-replay')?.addEventListener('click',reset);
 for(const key of ['aging','pairCost'])app.querySelector(`#${key}`)?.addEventListener('change',event=>attempt(()=>change(configure(s,{[key]:Number(event.target.value)}),'Value-cost assumption updated. Effort estimates are separate.')));
 app.querySelectorAll('[data-policy]').forEach(b=>b.onclick=()=>attempt(()=>{const c=comparePolicy(s,b.dataset.policy);comparisons=comparisons.filter(x=>x.id!==c.id);comparisons.push(c);save();render();}));
 app.querySelector('#budget')?.addEventListener('change',event=>attempt(()=>change(setBudget(s,s.quarter,Number(event.target.value)),'This quarter’s capacity changed explicitly.')));
 app.querySelectorAll('[data-budget]').forEach(el=>el.onchange=()=>attempt(()=>change(setBudget(s,+el.dataset.budget,+el.value),'Capacity schedule changed; settled budgets are kept.')));
 app.querySelectorAll('[data-effort-id]').forEach(el=>el.onchange=()=>attempt(()=>change(editEffort(s,el.dataset.effortId,el.dataset.effortField,+el.value),'Effort estimate changed before this request settles.')));
 for(const key of ['aging','pair'])app.querySelector('#effort-'+key)?.addEventListener('change',event=>attempt(()=>change(configureCapacity(s,{[key]:+event.target.value}),'Effort assumption changed. Value-point assumptions kept.')));
 app.querySelectorAll('[data-job]').forEach(el=>el.onchange=()=>attempt(()=>{const jobs=copy(s.capacity.jobs),j=jobs.find(x=>x.id===el.dataset.job);j[el.dataset.jobField]=el.dataset.jobField==='title'?el.value:+el.value;change(configureCapacity(s,{jobs}),'Core work assumption changed.');}));
 app.querySelector('#decision').onchange=event=>{undo.push(copy({s,comparisons,decision}));undo=undo.slice(-35);decision=event.target.value;app.querySelector('#undo').disabled=false;save();say('Decision note saved.');};
 app.querySelector('#export').onclick=()=>downloadText('exceptions-run.md',markdown({s,comparisons,decision}),'text/markdown');app.querySelector('#json').onclick=()=>downloadText('exceptions-run.json',portable({s,comparisons,decision}),'application/json');app.querySelector('#import').onclick=()=>document.querySelector('#import-file').click();
 app.querySelector('#recovery')?.addEventListener('click',()=>downloadText('exceptions-recovery.json',recovery||JSON.stringify({s,comparisons,decision}),'application/json'));app.querySelector('#resume')?.addEventListener('click',()=>{paused=false;recovery=null;save();render();});
}
document.querySelector('#import-file').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>1000000)throw Error('Choose a file under 1 MB.');const next=parse(await file.text());undo.push(copy({s,comparisons,decision}));undo=undo.slice(-35);({s,comparisons,decision}=next);message='Run imported. Undo restores the previous run.';save();render();say(message);}catch(error){message=error.message;render();say(message);}event.target.value='';};
window.addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==JSON.stringify({s,comparisons,decision})){paused=true;recovery=event.newValue;message='Another tab changed this run. Saving here is paused.';render();}});
window.addEventListener('pagehide',()=>{decision=document.querySelector('#decision')?.value||decision;save();});
window.exceptionsExperiment={getState:()=>copy(s),move:(id,lane)=>change(move(s,id,lane),'Plan updated.'),advance:()=>change(advance(s),'Quarter settled.')};render();
